    }
    if (object.class === "desk") {
      zones.push({
        zone_id: makeStableId("zone", `${object.object_id}:desk-pullout`),
        kind: "desk_pullout",
        entity_id: object.object_id,
        polygon: frontAccessZoneForObject(object, 0.9),
