tmpdir=$(mktemp -d)
node --input-type=module <<'EOF'
import { readFileSync } from 'node:fs';
import { createRoomPlanApiServer } from './apps/api/src/server.ts';
import { RoomPlanCaptureService } from './apps/api/src/roomplan-ingest.ts';

const storage = process.env.TMPDIR_PATH;
const request = JSON.parse(readFileSync('./fixtures/roomplan/bedroom-primary/capture-request.json','utf8'));

const server = createRoomPlanApiServer({ storage_directory: storage, token_secret: 'secret', handoff_base_url: 'https://roomview.local/h' });
await new Promise((resolve)=>server.listen(0,'127.0.0.1',resolve));
const address = server.address();
const response = await fetch(`http://127.0.0.1:${address.port}/captures/roomplan`, { method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify(request) });
if (response.status !== 200) throw new Error(`unexpected status ${response.status}`);
const payload = await response.json();
await new Promise((resolve,reject)=>server.close((err)=>err?reject(err):resolve()));
const hydrated = new RoomPlanCaptureService({ storage_directory: storage, token_secret: 'secret', handoff_base_url: 'https://roomview.local/h' });
const scene = hydrated.getScene(payload.scene_id);
if (!scene) throw new Error('scene was not reloaded from durable storage');
console.log(JSON.stringify({ scene_id: payload.scene_id, snapshot_id: payload.scene_snapshot_id, reloaded: !!scene }));
EOF

